'use client'

const ILLUSTRATION_WIDTHS = [
  16, 32, 48, 64, 96, 128, 256, 384,
  640, 750, 828, 1080, 1200, 1600, 1920,
]

function illustrationWidth(requestedWidth: number) {
  return ILLUSTRATION_WIDTHS.find((width) => width >= requestedWidth)
    ?? ILLUSTRATION_WIDTHS[ILLUSTRATION_WIDTHS.length - 1]
}

export default function myImageLoader({ src, width }: { src: string; width: number; quality?: number }) {
  const isRemote = src.startsWith('http') || src.startsWith('//');
  if (isRemote) {
    return `${src}?w=${width}`;
  }

  // If in development, use original to avoid needing to run optimization script constantly
  if (process.env.NODE_ENV === 'development') {
    return `${src}?w=${width}`;
  }

  // SVGs are vectors; skip the WebP optimization pipeline
  if (src.endsWith('.svg')) {
    return `${src}?w=${width}`;
  }

  // In production, use the pre-generated optimized WebP
  // src is like "/assets/images/Aura.png"
  // We want "/optimized/assets/images/Aura.webp"
  
  const fileNameWithExt = src.split('/').pop() || '';
  const directory = src.substring(0, src.lastIndexOf(fileNameWithExt)); // e.g. "/assets/images/"
  const fileName = fileNameWithExt.substring(0, fileNameWithExt.lastIndexOf('.')); // "Aura"

  if (directory === "/assets/illustrations/") {
    return `/optimized${directory}${fileName}-${illustrationWidth(width)}w.webp`;
  }

  return `/optimized${directory}${fileName}.webp?w=${width}`;
}
